                grid-template-columns: 1fr;
            }

            .mission-image {
                order: -1;
            }

            .stats-grid {
                grid-template-columns: repeat(2, 1fr);
            }

            .involve-grid {
                grid-template-columns: 1fr;
            }

            .donate-cta-inner {
                grid-template-columns: 1fr;
            }

            .footer-grid {
                grid-template-columns: repeat(2, 1fr);
            }

